## Fix: Enable AWS Config Recorder

Create a Config Recorder, the IAM role it assumes, a delivery channel, and a RecorderStatus to
start it. AWS will not start a recorder that has no delivery channel:

```typescript
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";

// IAM role AWS Config assumes, with the AWS managed policy for Config attached
const configRole = new aws.iam.Role("config-role", {
    assumeRolePolicy: {
        Version: "2012-10-17",
        Statement: [{
            Effect: "Allow",
            Principal: { Service: "config.amazonaws.com" },
            Action: "sts:AssumeRole",
        }],
    },
});

new aws.iam.RolePolicyAttachment("config-role-managed-policy", {
    role: configRole.name,
    policyArn: "arn:aws:iam::aws:policy/service-role/AWS_ConfigRole",
});

// S3 bucket the delivery channel writes configuration history and snapshots to
const configBucket = new aws.s3.Bucket("config-delivery");
const accountId = aws.getCallerIdentityOutput().accountId;

// Let the role deliver to that bucket
const configDeliveryPolicy = new aws.iam.RolePolicy("config-delivery-policy", {
    role: configRole.name,
    policy: {
        Version: "2012-10-17",
        Statement: [
            {
                Effect: "Allow",
                Action: ["s3:PutObject", "s3:PutObjectAcl"],
                Resource: pulumi.interpolate`${configBucket.arn}/AWSLogs/${accountId}/*`,
                Condition: { StringLike: { "s3:x-amz-acl": "bucket-owner-full-control" } },
            },
            {
                Effect: "Allow",
                Action: "s3:GetBucketAcl",
                Resource: configBucket.arn,
            },
        ],
    },
});

// Create Config Recorder
const recorder = new aws.cfg.Recorder("config-recorder", {
    recordingGroup: {
        allSupported: true,  // Record all supported resource types
        includeGlobalResourceTypes: true,  // Include global resources (IAM, etc.)
    },
    roleArn: configRole.arn,  // IAM role with Config permissions
});

// A delivery channel needs the recorder to exist, and the recorder will not start without one
const deliveryChannel = new aws.cfg.DeliveryChannel("config-delivery-channel", {
    s3BucketName: configBucket.bucket,
}, { dependsOn: [recorder, configDeliveryPolicy] });

// Activate the recorder
const recorderStatus = new aws.cfg.RecorderStatus("config-recorder-status", {
    name: recorder.name,
    isEnabled: true,  // Enable the recorder
}, { dependsOn: [deliveryChannel] });
```

